SELECT t.case_id, t.node_id AS component, t.label, t.previous_value, t.value AS current_value, t.contribution_delta, c.deviation, ABS(t.contribution_delta) AS abs_contribution, DENSE_RANK() OVER (PARTITION BY t.case_id ORDER BY ABS(t.contribution_delta) DESC, t.sequence_no) AS abs_contribution_rank, t.source_table, t.source_column, t.sequence_no FROM {{PUBLIC}}.calculation_trace t JOIN {{CURATED}}.case_summary c USING (case_id) WHERE t.node_type='COMPONENT'
